require_once __DIR__.'/../app/Core/DB.php';require_once __DIR__.'/../app/Services/AnggaranDocumentService.php';require_once __DIR__.'/../vendor/autoload.php';$db=DB::getInstance();$ok=static function($v,$m){if(!$v)throw new RuntimeException('FAIL: '.$m);echo "PASS: $m\n";};$scope=$db->query('SELECT kd_wilayah,kd_opd,tahun FROM dpa_neo WHERE is_deleted=0 ORDER BY id LIMIT 1')->fetch();$user=$scope+['username'=>'TRACE_PHASE15','type_user'=>'admin_opd'];foreach(['ssh','sbu','asb','hspk'] as $type)$ok((int)$db->query('SELECT COUNT(*) n FROM master_biaya WHERE tipe=? AND kd_wilayah=? AND tahun=? AND is_deleted=0',[$type,$scope['kd_wilayah'],$scope['tahun']])->fetch()['n']>=10,"minimal 10 dummy $type tersedia");foreach(['rkpd_neo','renja_neo','rka_neo','dpa_neo','rkpd_p_neo','renja_p_neo','rka_p_neo','dppa_neo'] as $table)$ok((int)$db->query("SELECT COUNT(DISTINCT kd_sub_keg) n FROM `$table` WHERE kd_wilayah=? AND kd_opd=? AND tahun=? AND is_deleted=0",[$scope['kd_wilayah'],$scope['kd_opd'],$scope['tahun']])->fetch()['n']>=5,"$table memiliki minimal lima subkegiatan");$service=new AnggaranDocumentService($user);foreach(['renja','rka','dpa','renja_p','rka_p','dppa'] as $logical){$groups=$service->groups($logical);$file=$service->exportExcel($logical);$book=PhpOffice\PhpSpreadsheet\IOFactory::load($file);$ok($book->getSheetCount()===count($groups)&&count($groups)>=5,"export $logical satu sheet per subkegiatan");$ok($book->getSheet(0)->getCell('A1')->getValue()!==null&&$book->getSheet(0)->getStyle('A1')->getFont()->getBold(),"export $logical memiliki judul dan format resmi");unlink($file);}echo "PHASE 15 TESTS COMPLETE\n";
